import{_ as u,a0 as a,w as s,s as r,ao as l,I as p,x as o,a1 as e,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"使用谷歌文檔在 Ubuntu 中對文本進行語音識別 | LCTT x X-CMD","titleTemplate":false,"description":"使用谷歌文檔在 Ubuntu 中對文本進行語音識別 | LCTT (202210) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用谷歌文檔在 Ubuntu 中對文本進行語音識別 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用谷歌文檔在 Ubuntu 中對文本進行語音識別 | LCTT (202210) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202210/20220926 Speech Recognition to Text in Linux, Ubuntu using Google Docs","title":"使用谷歌文檔在 Ubuntu 中對文本進行語音識別","tag":"202210","desc":""},"relativePath":"202210/20220926 Speech Recognition to Text in Linux, Ubuntu using Google Docs.md","filePath":"[post].md"}'),d={name:"202210/20220926 Speech Recognition to Text in Linux, Ubuntu using Google Docs.md"};function g(m,t,b,h,w,x){const n=a("Link");return s(),r("div",null,[t[24]||(t[24]=l('<h1 id="使用谷歌文檔在-ubuntu-中對文本進行語音識別" tabindex="-1">使用谷歌文檔在 Ubuntu 中對文本進行語音識別 <a class="header-anchor" href="#使用谷歌文檔在-ubuntu-中對文本進行語音識別" aria-label="Permalink to “使用谷歌文檔在 Ubuntu 中對文本進行語音識別”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202210/04/222403dhey2zwn1442u3n1.jpg" alt=""></p><blockquote><p>這就是在包括 Ubuntu 在內的 Linux 系統中將語音轉換為文本的方法。</p></blockquote><p>Linux 系統中可用的語音識別軟件不多，尤其是原生桌面應用。有一些可用的應用使用 IBM Watson 和其他 API 將語音轉換為文本，但它們的用户交互不友好，需要一些複雜的用户交互，例如用相應的語言進行一些編程或腳本編寫。</p><p>但是，沒有多少用户知道 <ruby>谷歌文檔<rt>Google Docs</rt></ruby> 使用自己的 AI 技術提供了高級語音識別，它可以通過 Chrome 訪問谷歌文檔使用。</p><p>任何用户都可以使用此功能將語音轉換為文本，而無需高級計算機知識。谷歌文檔的這個功能最好的一點是你可以在任何 Ubuntu 衍生版或任何支持 Chrome 的 Linux 發行版中使用它。</p><p>讓我們看看如何在 Ubuntu 中啓用它。</p><h3 id="如何將語音轉換為文本" tabindex="-1">如何將語音轉換為文本 <a class="header-anchor" href="#如何將語音轉換為文本" aria-label="Permalink to “如何將語音轉換為文本”">​</a></h3>',8)),p("p",null,[t[1]||(t[1]=o("先決條件是你應該在系統中安裝 Chrome 並擁有谷歌帳户。如果你沒有安裝 Chrome，你可以訪問 ",-1)),e(n,{href:"https://www.google.com/chrome"},{default:i(()=>[...t[0]||(t[0]=[o("此鏈接",-1)])]),_:1}),t[2]||(t[2]=o(" 並下載、安裝 Chrome。",-1))]),p("p",null,[t[4]||(t[4]=o("此外，如果你沒有谷歌帳户，你可以使用 ",-1)),e(n,{href:"https://accounts.google.com"},{default:i(()=>[...t[3]||(t[3]=[o("此鏈接",-1)])]),_:1}),t[5]||(t[5]=o(" 免費創建一個。",-1))]),t[25]||(t[25]=p("h4",{id:"步驟-1",tabindex:"-1"},[o("步驟 1 "),p("a",{class:"header-anchor",href:"#步驟-1","aria-label":"Permalink to “步驟 1”"},"​")],-1)),p("p",null,[t[7]||(t[7]=o("從 Chrome 打開 ",-1)),e(n,{href:"https://docs.google.com"},{default:i(()=>[...t[6]||(t[6]=[o("https://docs.google.com",-1)])]),_:1}),t[8]||(t[8]=o(" 並創建一個空白文檔。",-1))]),t[26]||(t[26]=l('<p><img src="https://www.debugpoint.com/wp-content/uploads/2018/07/Create-an-empty-doc.png" alt="創建一個空文檔"></p><h4 id="步驟-2" tabindex="-1">步驟 2 <a class="header-anchor" href="#步驟-2" aria-label="Permalink to “步驟 2”">​</a></h4><p>加載空白文檔後，從菜單中單擊“工具 &gt; 語音輸入”。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2018/07/Enable-Voice-Typing.png" alt="啓用語音輸入"></p><h4 id="步驟-3" tabindex="-1">步驟 3 <a class="header-anchor" href="#步驟-3" aria-label="Permalink to “步驟 3”">​</a></h4><p>在左側，你可以看到一個麥克風圖標。單擊麥克風圖標，Chrome 會首次要求允許通過瀏覽器訪問麥克風。單擊允許。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2018/07/Click-the-mic.png" alt="點擊麥克風"></p><p><img src="https://www.debugpoint.com/wp-content/uploads/2018/07/Allow-Docs-to-access-Mic.png" alt="允許文檔訪問麥克風"></p><p>默認情況下，它使用你的系統語言作為語音的檢測語言，同時將其轉換為文本；但是，你可以根據可用的語言列表將其更改為所需的任何語言。到目前為止，谷歌文檔支持和識別超過 60 多種語言，同時將它們轉換為文本。</p><h4 id="步驟-4" tabindex="-1">步驟 4 <a class="header-anchor" href="#步驟-4" aria-label="Permalink to “步驟 4”">​</a></h4><p>單擊允許後，麥克風圖標將變為橙色，現在它已準備好接受或識別你的聲音。開始説任何你想説的話，瞧！你將看到你的演講被轉換為文本並寫入文檔。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2018/07/Voice-to-Text-In-action.png" alt="正在進行語音轉文字"></p><p>完成了。你已通過谷歌 Chrome 和谷歌文檔在 Ubuntu 中成功地將語音轉換為文本。</p><p>所有 Linux 用户都可以免費使用這個很棒的功能。如果你知道其他可以在 Linux 中將語音轉換為文本的應用，請在下方的評論區發表評論。另外，讓我知道你是否覺得這篇文章有用。</p><h3 id="故障排除" tabindex="-1">故障排除 <a class="header-anchor" href="#故障排除" aria-label="Permalink to “故障排除”">​</a></h3><p>如果上述功能在你的瀏覽器中不起作用，請務必查看以下內容。</p><ul><li>打開設置窗口（在 Ubuntu 或其他發行版的 GNOME 桌面中）。</li><li>轉到“隱私 &gt; 麥克風”。</li><li>並確保它已啓用。</li></ul><p><img src="https://www.debugpoint.com/wp-content/uploads/2018/07/Check-Microphone-settings-in-Ubuntu.jpg" alt="檢查 Ubuntu 中的麥克風設置"></p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>雖然，最近有一種基於雲的解決方案可用，例如 Amazon Polly 等。但它們的價格很高。另外還需要一些有用的知識。</p><p>而谷歌 Chrome 的內置語音識別功能簡單易用。雖然它有點慢，但它可以為普通用户完成工作。</p><p>也就是説，我希望本指南可以幫助你將語音轉換為文本，如果你知道這樣的免費應用，請在評論區告訴我。</p><hr>',23)),p("p",null,[t[10]||(t[10]=o("via: ",-1)),e(n,{href:"https://www.debugpoint.com/speech-recognition-to-text-in-linux-ubuntu-using-google-docs/"},{default:i(()=>[...t[9]||(t[9]=[o("https://www.debugpoint.com/speech-recognition-to-text-in-linux-ubuntu-using-google-docs/",-1)])]),_:1})]),p("p",null,[t[15]||(t[15]=o("作者：",-1)),e(n,{href:"https://www.debugpoint.com/author/admin1/"},{default:i(()=>[...t[11]||(t[11]=[o("Arindam",-1)])]),_:1}),t[16]||(t[16]=o(" 選題：",-1)),e(n,{href:"https://github.com/lkxed"},{default:i(()=>[...t[12]||(t[12]=[o("lkxed",-1)])]),_:1}),t[17]||(t[17]=o(" 譯者：",-1)),e(n,{href:"https://github.com/geekpi"},{default:i(()=>[...t[13]||(t[13]=[o("geekpi",-1)])]),_:1}),t[18]||(t[18]=o(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:i(()=>[...t[14]||(t[14]=[o("wxy",-1)])]),_:1})]),p("p",null,[t[21]||(t[21]=o("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[19]||(t[19]=[o("LCTT",-1)])]),_:1}),t[22]||(t[22]=o(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:i(()=>[...t[20]||(t[20]=[o("Linux中國",-1)])]),_:1}),t[23]||(t[23]=o(" 榮譽推出",-1))])])}const k=u(d,[["render",g]]);export{C as __pageData,k as default};
